typealias Bytes = [UInt8]

func cstring(_ b: Bytes) -> Bytes {
  if let nul = b.firstIndex(of: 0) { return Array(b[..<nul]) }
  return b
}

func text(_ b: Bytes) -> String {
  String(decoding: cstring(b), as: UTF8.self)
}

